  "연결 시작 실패. Supabase 프로젝트에서 이 로그인 방식과 계정 연결(manual linking) 활성화 확인 필요": "लिंक शुरू नहीं हो सका। जाँचें कि Supabase प्रोजेक्ट में यह साइन-इन तरीका और मैन्युअल अकाउंट लिंकिंग चालू हैं",
