  "\"여기서 뭐 둘래?\" 수 투표 전송 (FEN을 비우면 포지션 선택 창)": "“यहाँ आप क्या खेलेंगे?” चाल पोल भेजें (FEN खाली छोड़ने पर पोज़ीशन चुनने की विंडो खुलती है)",
