  "/user 페이지 우상단 X 버튼을 점 3개 메뉴(신고·차단)로 교체했습니다. 좌상단에 @아이디 표시합니다.": "/user पेज के ऊपर दाएँ कोने के X बटन की जगह तीन बिंदुओं वाला मेनू (रिपोर्ट/ब्लॉक) लगाया गया। ऊपर बाएँ में @ID दिखता है।",
  "신고 사유를 체크박스로 중복 선택했습니다. 개발자 모드에서 신고자·신고 대상 아이디와 신고 내용(최근 대화 포함) 열람 추가했습니다.": "रिपोर्ट के कारण अब चेकबॉक्स से एक से अधिक चुने जा सकते हैं। डेवलपर मोड में रिपोर्ट करने वाले और रिपोर्ट किए गए का ID और रिपोर्ट की सामग्री (हाल की बातचीत सहित) देखी जा सकती है।",
  "채팅창 상단에 '최근 활동' 표시합니다. 신고·차단 버튼을 점 3개 메뉴로 통합했습니다.": "चैट के ऊपर ID के नीचे 'अंतिम गतिविधि' दिखती है। रिपोर्ट और ब्लॉक बटन एक तीन-बिंदु मेनू में मिला दिए गए।",
  "채팅의 모든 요소(카드·알림 포함)에 반응 가능 추가했습니다. 더블클릭하면 하트 반응 추가했습니다. 반응 이모지를 말풍선에 붙여 표시합니다.": "चैट के हर तत्व (कार्ड और सूचनाओं सहित) पर प्रतिक्रिया दी जा सकती है। डबल-क्लिक करने पर दिल की प्रतिक्रिया लगती है। प्रतिक्रिया इमोजी अब बबल से सटे दिखते हैं।",
  "대국 신청 카드의 띄어쓰기 오류를 수정했습니다. '끝난 대국'을 '대국 종료됨'으로 표기합니다.": "खेल अनुरोध कार्ड में स्पेस की गलती ठीक की गई। 'समाप्त खेल' की जगह अब 'खेल समाप्त' लिखा आता है।",
  "미니게임 육각형 엠블럼에서 'MiniGame' 글자 삭제했습니다.": "मिनी-गेम षट्कोण प्रतीक से 'MiniGame' लिखावट हटाई गई।",
  "신고 사유 (중복 선택 가능)": "रिपोर्ट के कारण (एक से अधिक चुन सकते हैं)",
  "신고한 메시지와 최근 대화는 검토를 위해 운영진에게 전달. 상대에게는 알리지 않음": "रिपोर्ट किया गया संदेश और हाल की बातचीत समीक्षा के लिए टीम को भेजी जाती है। दूसरे उपयोगकर्ता को सूचित नहीं किया जाता",
