  "최근 활동 : {0}": "अंतिम गतिविधि : {0}",
  "분석 탭 수 블록의 공개 데이터 통계가 '- / -'로 남거나 채택률 막대가 비던 문제를 수정했습니다. 통계 조회가 실패하면 자동으로 다시 시도 추가했습니다.": "विश्लेषण टैब के चाल ब्लॉक में सार्वजनिक डेटा आँकड़े '— / —' रह जाने या अपनाने की पट्टी खाली रहने की समस्या ठीक की। आँकड़े लाने में विफल होने पर अपने आप दोबारा कोशिश होती है।",
  "프로필의 통계 전환 버튼을 'OpenChess'·'외부 사이트' 글자로 변경했습니다.": "प्रोफ़ाइल के आँकड़ा बदलने वाले बटन अब 'OpenChess' और 'बाहरी साइट' के नाम से दिखते हैं।",
  "미니게임 랭킹 화면의 중복된 '로비' 버튼 삭제했습니다.": "मिनी-गेम रैंकिंग स्क्रीन से दोहराया गया 'लॉबी' बटन हटाया।",
  "일반 대국 전적·레이팅·랭킹 추가했습니다. 랜덤 매칭 결과가 미니게임과 같은 형태의 랭킹에 반영했습니다.": "सामान्य खेल के लिए रिकॉर्ड, रेटिंग और रैंकिंग जोड़ी गई। रैंडम मैचिंग के नतीजे मिनी-गेम जैसी ही रैंकिंग में गिने जाते हैं।",
  "나이트 레이스 이동 수 제한 삭제했습니다. 제한시간 안이면 몇 수든 이동 가능 추가했습니다.": "नाइट रेस में चालों की सीमा हटाई गई। समय सीमा के भीतर जितनी चाहें उतनी चालें चल सकते हैं।",
  "나이트 레이스 혼자 플레이에서 목표에 못 닿으면 정산 전에 최단 경로를 금색 화살표로 표시합니다.": "अकेले नाइट रेस में लक्ष्य तक न पहुँचने पर राउंड सारांश से पहले सबसे छोटा रास्ता सुनहरे तीरों से दिखाया जाता है।",
  "나이트 레이스 거리 판정 연출이 칸에서 어긋나던 문제를 수정했습니다.": "नाइट रेस में दूरी से फ़ैसले वाला एनीमेशन खानों से खिसक जाता था, इसे ठीक किया गया।",
  "무한 체크메이트 포지션을 수천 개로 확대했습니다. 백랭크·스모더드 등 다양한 체크메이트 모양을 고르게 출제하며, 한 번 나온 포지션은 모두 소진하기 전까지 다시 나오지 않습니다.": "अनंत शहमात में अब हज़ारों पोज़ीशन हैं। बैक-रैंक और स्मदर्ड जैसे कई तरह के शहमात पैटर्न बराबर आते हैं, और जब तक सभी न आ जाएँ कोई पोज़ीशन दोबारा नहीं आती।",
  "무한 체크메이트 대전에서 상대의 진행 상황(수순 탐색 중·정확한 수순·실패·체크메이트 성공) 표시합니다.": "अनंत शहमात के मुक़ाबलों में अब प्रतिद्वंद्वी की प्रगति दिखती है: क्रम खोज रहा है, सही क्रम, विफल, या शहमात सफल।",
  "무한 체크메이트 동점 시 결과 화면 전에 등급별 성공 수를 하나씩 비교하는 정산 화면 추가했습니다.": "अनंत शहमात में बराबरी होने पर नतीजे से पहले एक टाईब्रेकर स्क्रीन ग्रेड के अनुसार सफलताओं की तुलना करती है।",
  "일반 대국 랭킹, 나이트 레이스 개선, 무한 체크메이트 대폭 확장, 공개 데이터 통계 표시 수정했습니다.": "सामान्य खेल रैंकिंग, नाइट रेस में सुधार, अनंत शहमात का बड़ा विस्तार, सार्वजनिक डेटा आँकड़ों में सुधार।",
  "일반 대국 랭킹, 나이트 레이스 최단 경로 화살표, 체크메이트 포지션 수천 개, 상대 진행 상황 표시합니다.": "सामान्य खेल रैंकिंग, नाइट रेस में सबसे छोटे रास्ते के तीर, हज़ारों शहमात पोज़ीशन, प्रतिद्वंद्वी की प्रगति",
  "일반 대국 랭킹, 나이트 레이스 최단 경로 화살표, 체크메이트 포지션 수천 개, 상대 진행 상황 표시": "सामान्य खेल रैंकिंग, नाइट रेस में सबसे छोटे रास्ते के तीर, हज़ारों शहमात पोज़ीशन, प्रतिद्वंद्वी की प्रगति",
