  "아직 분석되지 않은 수입니다.": "ऐसी चाल जिसका अभी विश्लेषण नहीं हुआ",
  "상대의 응징 수순은 {0}입니다.": "प्रतिद्वंद्वी की सज़ा देने वाली लाइन, {0}",
