  "분석 불가. 엔진 준비 상태 확인": "विश्लेषण संभव नहीं। जाँचें कि इंजन तैयार है",
  "이미지 생성 실패": "इमेज नहीं बन सकी",
  "OpenChess 리뷰": "OpenChess रिव्यू",
