  "일일 퀘스트 오프닝. 눌러서 퀘스트 보기": "दैनिक क्वेस्ट ओपनिंग। क्वेस्ट देखने के लिए टैप करें",
  "일일 퀘스트 오프닝": "दैनिक क्वेस्ट ओपनिंग",
  "퀘스트": "क्वेस्ट",
  "{0} 분석": "{0} विश्लेषण करें",
