  "{0} 동안 강제 체크메이트 포지션(공격 기회)이 계속 주어짐. 더 많이 성공시킨 쪽 승리": "{0} तक जबरन शहमात की पोज़ीशन (हमले के मौके) लगातार मिलती रहती हैं। ज़्यादा सफल करने वाला जीतता है",
  "한 수라도 틀리면 그 기회는 실패, 바로 다음 기회로 이동": "एक भी चाल गलत हुई तो वह मौका विफल, सीधे अगले मौके पर",
  "짧은 메이트일수록 좋은 등급. {0}이 좋은 등급을 받을 확률이 높음": "जितना छोटा मेट, उतनी बेहतर श्रेणी। {0} को अच्छी श्रेणी मिलने की संभावना ज़्यादा है",
  "퍼즐 레이팅이 낮은 쪽": "कम पहेली रेटिंग वाला पक्ष",
  "동점이면 긴 메이트(4수 이상 → 3수 → 2수 → 1수) 성공 수부터 비교, 그래도 같으면 레이팅이 높은 쪽 승리": "बराबरी पर पहले लंबे मेट (4+ → 3 → 2 → 1) की सफलताओं की तुलना होती है; फिर भी बराबर हो तो ऊँची रेटिंग वाला जीतता है",
  "3분 기록 도전": "3 मिनट का रिकॉर्ड चैलेंज",
  "3분, 최고 {0}회": "3 मिनट, सर्वश्रेष्ठ {0}",
  "내 레이팅 {0}": "मेरी रेटिंग {0}",
  "대기열 합류 실패. 잠시 후 다시 시도": "कतार में शामिल नहीं हो सके। थोड़ी देर बाद फिर कोशिश करें",
  "{0} 봇": "{0} बॉट",
  "생각하는 중...": "सोच रहा है...",
