  "이탈리안 게임부터 킹스 갬빗까지. 도감 탭의 대표 오프닝 정석 수순을 실제 기보 그대로 체스보드에 재현합니다": "इटैलियन गेम से किंग्स गैम्बिट तक। ओपनिंग्स टैब की प्रतिनिधि ओपनिंग्स की मानक चालें असली गेम रिकॉर्ड की तरह बोर्ड पर दोहराई जाती हैं",
  "그랜드마스터 트로피": "ग्रैंडमास्टर ट्रॉफ़ी",
  "최종 티어": "अंतिम टियर",
  "아이언에서 시작해 여섯 단계를 모두 넘어야 도달하는 일곱 번째, 마지막 티어입니다": "आयरन से शुरू करके सभी छह चरण पार करने पर पहुँचा जाने वाला सातवाँ और आख़िरी टियर",
  "달성 조건": "प्राप्त करने की शर्त",
  "퍼즐을 풀어 누적 {0}를 모으면(아이언→브론즈→실버→골드→다이아몬드→마스터 순서로 전부 돌파) 도달합니다. 이후에도 XP는 계속 쌓이고, {1}마다 프레스티지 별(★) 1개가 추가됩니다": "पहेलियाँ हल करके कुल {0} इकट्ठा करने पर (आयरन → ब्रॉन्ज़ → सिल्वर → गोल्ड → डायमंड → मास्टर क्रम से सब पार करके) यहाँ पहुँचते हैं। इसके बाद भी XP जुड़ता रहता है, और हर {1} पर 1 प्रेस्टीज सितारा (★) जुड़ता है",
  "그랜드마스터만의 혜택": "केवल ग्रैंडमास्टर के लाभ",
  "오로라처럼 일렁이는 전용 그러데이션 배지와 프레스티지 별(★) 카운터로 구분됩니다": "ऑरोरा की तरह लहराते ख़ास ग्रेडिएंट बैज और प्रेस्टीज सितारे (★) के काउंटर से अलग पहचान",
  "코인으로 살 수 없는 전용 체스보드·기물 스킨이 티어 달성과 동시에 해금됩니다. 상점에서 바로 장착할 수 있습니다": "कॉइन से न खरीदे जा सकने वाली ख़ास बोर्ड और मोहरों की स्किन टियर हासिल करते ही अनलॉक हो जाती हैं। शॉप में तुरंत पहन सकते हैं",
  "친구 목록·유저 검색·티어 리더보드에서 골드빛 테두리와 왕관 아이콘으로 강조됩니다": "दोस्तों की सूची, यूज़र खोज और टियर लीडरबोर्ड में सुनहरे किनारे और ताज के आइकन से उभारा जाता है",
  "티어 단계": "टियर के चरण",
