  "내 대국을 리뷰하다가 최선·유일·탁월 수에서 유산으로 남기기를 누르면 게시물로 쌓임": "अपने खेल की समीक्षा करें और सर्वश्रेष्ठ, अकेली या शानदार चाल पर विरासत के रूप में सहेजें दबाएँ, पोस्ट बन जाएगी",
  "유산이 가득 참 (최대 {0}개)": "विरासत भर गई है (अधिकतम {0})",
  "가장 약한 구간": "सबसे कमज़ोर चरण",
  "성장 요약": "प्रगति सारांश",
  "약점 진단": "कमज़ोरी निदान",
