  "학습 탭은 내 성장을 모아 둔 곳입니다.": "लर्न टैब वह जगह है जहाँ आपकी प्रगति जमा होती है।",
  "내 대국을 5판 이상 리뷰하면 열립니다. 모자랄 때는 게이지 바로 남은 판 수를 알려 줍니다.": "अपने 5 या अधिक खेल रिव्यू करने पर यह खुलता है। तब तक गेज बार बताता है कि कितने बाकी हैं।",
  "대국마다 오프닝, 전적, 탁월한 수와 유일한 수의 개수가 보입니다. 연두색 버튼으로 바로 리뷰할 수 있습니다.": "हर खेल में ओपनिंग, रिकॉर्ड और शानदार व एकमात्र चाल की संख्या दिखती है। हरे बटन से तुरंत रिव्यू कर सकते हैं।",
  "레슨은 갈래를 따라 순서대로 열리고, 오프닝 원칙부터 시작합니다.": "लेसन शाखाओं के साथ क्रम से खुलते हैं और ओपनिंग सिद्धांतों से शुरू होते हैं।",
  "리뷰한 대국이 {0}판 이상이면 성장 분석이 열림": "{0} या अधिक खेल रिव्यू करने पर ग्रोथ विश्लेषण खुलता है",
  "{0}판 더 리뷰하면 열림": "{0} और खेल रिव्यू करने पर खुलेगा",
  "최근 대국의 연두색 리뷰 버튼으로 내 대국을 리뷰하면 한 판씩 쌓임": "हाल के खेलों में हरे रिव्यू बटन से अपने खेल रिव्यू करने पर वे एक-एक करके जुड़ते हैं",
