  "퀸사이드 캐슬링(캐슬링한 대국 중)": "क्वीनसाइड कैसलिंग (कैसलिंग वाले गेम में)",
  "기물을 잡는 수의 비율": "मोहरा जीतने वाली चालों का अनुपात",
  "체크를 거는 수의 비율": "शह देने वाली चालों का अनुपात",
