  "다른 언어로 쓴 글 자동 번역": "दूसरी भाषाओं में लिखे पाठ का स्वतः अनुवाद",
  "수 설명·프로필 소개글을 내 언어로 번역해 보여줌. 채팅 메시지는 번역하지 않음": "चाल के नोट और प्रोफ़ाइल परिचय आपकी भाषा में अनुवाद करके दिखाए जाते हैं। चैट संदेश कभी अनुवादित नहीं होते",
  "번역할 때 글이 번역 서비스(Google Gemini)로 전송됨": "अनुवाद करते समय पाठ एक अनुवाद सेवा (Google Gemini) को भेजा जाता है",
  "Google(Gemini API): 자동 번역을 켠 이용자가 수 설명·프로필 소개글을 볼 때 해당 글을 번역 목적으로만 전송. 번역문은 작성자 정보 없이 30일 이내 보관 후 삭제하며, 채팅 메시지는 전송하지 않음": "Google (Gemini API): अनुवाद चालू रखने वाला उपयोगकर्ता जब चाल का नोट या प्रोफ़ाइल परिचय देखता है, तो वह पाठ केवल अनुवाद के लिए भेजा जाता है। अनुवाद लेखक की जानकारी के बिना अधिकतम 30 दिन रखे जाते हैं, फिर हटा दिए जाते हैं। चैट संदेश कभी नहीं भेजे जाते",
