  "{0}에 있는 {1:을/를} 잃게 됩니다.": "{0} पर {1} के खोने का खतरा",
  "{0}의 {1:을/를} 이대로 두면 잃게 됩니다.": "{0} पर {1} को छोड़ दिया तो हानि",
  "지금대로면 {0}에 있는 {1:을/를} 잃습니다.": "{0} पर {1} अभी खोने वाला है",
  "{0}에 있는 {1:이/가} 당장 위험하지만, 엔진에 의하면 문제없는 수입니다.": "{0} पर {1} असुरक्षित है, फिर भी इंजन के अनुसार चाल ठीक है",
  "{0}의 {1:이/가} 위험을 안고 있지만, 엔진에 의하면 괜찮은 수입니다.": "{0} पर {1} जोखिम में है, पर इंजन इसे मंज़ूर करता है",
  "{0}의 {1:을/를} 잃을 수 있어도, 엔진에 의하면 좋은 수입니다.": "{0} पर {1} खो सकता है, फिर भी इंजन के अनुसार अच्छी चाल",
  "이 수는 상대 {0:을/를} 위협합니다.": "प्रतिद्वंद्वी के {0} को खतरा",
  "상대 {0:이/가} 이 수의 위협을 받고 있습니다.": "प्रतिद्वंद्वी का {0} निशाने पर, खतरा",
  "이제 상대 {0:을/를} 위협하고 있습니다.": "इस चाल से प्रतिद्वंद्वी के {0} को खतरा बनता है",
  "상대 {0:이/가} 걸려 있습니다. 잡을 기회입니다.": "प्रतिद्वंद्वी का {0} असुरक्षित। पकड़ने का मौका",
  "상대 {0:을/를} 잡을 수 있는 상황입니다.": "प्रतिद्वंद्वी का {0} पकड़ा जा सकता है",
  "아직 상대 {0:이/가} 방치돼 있습니다. 놓치지 말아야 합니다.": "प्रतिद्वंद्वी का {0} अरक्षित है। मौका न चूकें",
  "{0:을/를} 잡지 않았지만 여전히 좋은 수입니다.": "{0} नहीं लिया, फिर भी अच्छी चाल",
  "{0:을/를} 잡을 수도 있었지만, 이 수도 충분히 좋습니다.": "{0} ले सकते थे, पर यह चाल भी पर्याप्त है",
  "당장 {0:을/를} 안 잡아도 이 수면 충분합니다.": "अभी {0} न लेना भी काफ़ी है",
  "상대 {0:을/를} 잡는 게 최선이었지만, 이 수도 여전히 좋습니다.": "प्रतिद्वंद्वी का {0} लेना सबसे अच्छा था। यह चाल भी अच्छी है",
  "사실 {0:을/를} 잡을 수 있었습니다. 그래도 이 수 역시 좋은 선택입니다.": "असल में {0} लिया जा सकता था। यह भी अच्छा विकल्प है",
  "{0:을/를} 잡는 게 최선이었으며, 다만 이 수도 나쁘지 않습니다.": "{0} लेना सबसे अच्छा था, पर यह चाल भी बुरी नहीं",
  "유리한 상황에서의 기물 교환은 게임을 쉽고 안정적으로 풀어가는 좋은 방법입니다.": "आगे हों तो मोहरों की अदला-बदली स्थिति सरल करने का अच्छा तरीका है",
  "이기고 있을 때 기물을 교환해 상황을 단순하게 만드는 좋은 선택입니다.": "आगे चलते समय मोहरों की अदला-बदली करके स्थिति सरल बनाना अच्छा चुनाव है।",
  "유리할 때는 기물을 바꿔가며 안정적으로 승리를 굳히는 게 좋습니다.": "आगे हों तो मोहरे बदलकर जीत पक्की करें",
  "지고 있을 때는 기물 교환을 피하는 게 좋지만, 이 교환은 불가피한 최선의 선택이었습니다.": "पीछे चलते समय मोहरों की अदला-बदली से बचना बेहतर है, पर यह अदला-बदली अनिवार्य और सबसे अच्छा चुनाव थी।",
  "기물 교환은 원래 피해야 하는 상황이지만, 이 교환만큼은 어쩔 수 없는 최선이었습니다.": "ऐसी स्थिति में आम तौर पर मोहरों की अदला-बदली से बचना चाहिए, पर यह अदला-बदली मजबूरी में सबसे अच्छी थी।",
  "지고 있는 상황에서도 이 교환은 최선으로 불가피했습니다.": "पीछे होने पर भी यह अदला-बदली सर्वश्रेष्ठ है",
  "지고 있을 때는 기물 교환을 피하는 게 좋지만, 이 교환은 좋은 선택이었습니다.": "पीछे चलते समय मोहरों की अदला-बदली से बचना बेहतर है, पर यह अदला-बदली अच्छा चुनाव थी।",
  "원래는 피해야 할 기물 교환이지만, 이번엔 괜찮은 선택이었습니다.": "आम तौर पर बचने लायक मोहरों की अदला-बदली, पर इस बार यह ठीक चुनाव था।",
  "지고 있는 상황이라도 이 교환만큼은 나쁘지 않은 선택이었습니다.": "पीछे होने पर भी यह अदला-बदली बुरी नहीं",
  "유리한 상황이라도 목적 없는 기물 교환은 손해가 될 수 있습니다. 기물 교환은 목적을 갖고 해야 합니다.": "आगे होने पर भी बिना उद्देश्य मोहरों की अदला-बदली नुकसान दे सकती है, मोहरों की अदला-बदली उद्देश्य के साथ करें।",
