  "켜면 아래 도구와 편집 기능 사용 가능": "नीचे के टूल और संपादन सुविधाएँ खुलती हैं",
  "임명 권한만 빼고 모두 사용 가능": "नियुक्ति अधिकार छोड़कर सभी सुविधाएँ",
