  "OC 코인, 경험치, 티어를 바꿔서 연출 확인": "OC सिक्के, XP और टियर बदलकर प्रभाव तुरंत देखें",
  "퍼즐 콘텐츠": "पहेली सामग्री",
  "일일 퍼즐, 일괄 재생성, 검사": "दैनिक पहेली, थोक पुनर्निर्माण, जाँच",
  "신고": "रिपोर्ट",
  "들어온 신고 보기, 처리": "प्राप्त रिपोर्ट देखें और संभालें",
  "화면 불러오기 실패": "पेज लोड नहीं हो सका",
  "일시적인 문제 발생. 새로고침하면 대부분 해결.": "कुछ देर के लिए समस्या आ गई। रीलोड करने से अक्सर ठीक हो जाता है।",
  "새로고침": "रीलोड करें",
  "오류 내용 보기": "त्रुटि का विवरण देखें",
  "프로필에 최근 10판 퍼포먼스 레이팅 추가했습니다. OpenChess·외부 사이트 모두 전체 기간 전적 아래에 표시합니다.": "प्रोफ़ाइल में पिछले 10 खेलों की प्रदर्शन रेटिंग जोड़ी गई। OpenChess और बाहरी साइट दोनों में कुल रिकॉर्ड के नीचे दिखती है।",
  "퍼포먼스 레이팅은 상대·본인 레이팅과 무관하게 수의 질만으로 계산 추가했습니다. 이론·탁월한 수·유일한 수는 올리고 블런더는 내리되 영향은 제한했습니다.": "प्रदर्शन रेटिंग आपकी या प्रतिद्वंद्वी की रेटिंग से स्वतंत्र, केवल चालों की गुणवत्ता से तय होती है। थ्योरी, शानदार और एकमात्र चालें इसे बढ़ाती हैं, ब्लंडर घटाते हैं, पर असर सीमित रहता है।",
  "리뷰해서 분석이 저장된 대국만 반영했습니다. 분석된 대국이 3판 미만이면 표시하지 않습니다. OpenChess 대국도 리뷰하면 분석이 서버에 저장했습니다.": "केवल वही खेल गिने जाते हैं जिनका समीक्षा विश्लेषण सहेजा गया है। 3 से कम विश्लेषित खेल होने पर कुछ नहीं दिखता। OpenChess खेल की समीक्षा करने पर उसका विश्लेषण सर्वर पर सहेजा जाता है।",
  "리뷰 요약 화면의 퍼포먼스 레이팅 삭제했습니다. 한 판 값은 오차가 커서 여러 판을 합친 값으로만 표시합니다.": "समीक्षा सारांश से प्रदर्शन रेटिंग हटाई गई। एक खेल का मान बहुत अनिश्चित होता है, इसलिए केवल कई खेलों का संयुक्त मान दिखता है।",
  "설정의 개발자 도구를 카드 하나로 통합했습니다. 개발자 모드 토글을 이 카드로 옮기고 다른 토글과 같은 크기로 변경, 도구는 기능별 4개 묶음으로 접고 펼침 추가했습니다.": "सेटिंग्स के डेवलपर टूल एक कार्ड में मिलाए गए। डेवलपर मोड टॉगल उसी कार्ड में मानक आकार में है और टूल कार्य के अनुसार चार समूहों में खुलते-बंद होते हैं।",
  "320px 폭 화면에서 헤더의 계정 칩이 잘리던 문제를 수정했습니다. 헤더 아이콘 버튼의 터치 범위 확대했습니다.": "320px चौड़े फ़ोन पर हेडर का अकाउंट चिप कटने की समस्या ठीक की गई। हेडर आइकन बटनों का टच क्षेत्र बढ़ाया गया।",
  "분석 탭 엔진 수순의 오른쪽 끝에 페이드를 넣어 옆으로 이어짐을 표시합니다.": "विश्लेषण टैब में इंजन लाइनों के दाएँ किनारे पर फ़ेड जोड़ा गया ताकि पता चले कि आगे भी है।",
  "시간 규정 표기를 '불릿'으로 통일, 값이 없을 때 긴 줄표 대신 '-' 표시합니다.": "समय नियम का नाम 'बुलेट' के रूप में एक समान किया गया और मान न होने पर लंबे डैश की जगह '-' दिखता है।",
  "접속 중 첫 화면이 나오기 전에 어두운 시작 화면과 로고 표시합니다.": "पहली स्क्रीन तैयार होने से पहले लोगो के साथ गहरी शुरुआती स्क्रीन दिखती है।",
  "접속하자마자 흰 화면이 뜨던 문제를 수정했습니다. 화면 오류가 나면 안내와 새로고침 버튼을 표시하고, 배포 직후 파일을 못 찾으면 한 번 자동 새로고침 추가했습니다.": "पेज खुलते ही सफ़ेद स्क्रीन आने की समस्या ठीक की गई। स्क्रीन त्रुटि पर संदेश और रीलोड बटन दिखता है, और अपडेट के तुरंत बाद फ़ाइलें न मिलने पर पेज एक बार अपने आप रीलोड होता है।",
  "개발자 도구 카드의 불필요한 '}' 글자와 공동 개발자 '추가' 버튼 찌그러짐 수정했습니다.": "डेवलपर टूल कार्ड में अनावश्यक '}' अक्षर और सह-डेवलपर 'जोड़ें' बटन के सिकुड़ने की समस्या ठीक की गई।",
  "프로필 최근 10판 퍼포먼스 레이팅, 개발자 도구 정리, 흰 화면 방지했습니다.": "प्रोफ़ाइल में पिछले 10 खेलों की प्रदर्शन रेटिंग, डेवलपर टूल का सुधार, सफ़ेद स्क्रीन का समाधान।",
  "프로필 최근 10판 퍼포먼스 레이팅 추가했습니다.": "प्रोफ़ाइल प्रदर्शन रेटिंग, पिछले 10 खेल",
