  "조건에 맞는 변경 내용이 없습니다.": "शर्त से मेल खाने वाला कोई बदलाव नहीं है।",
  "/roulette [수]": "/roulette [चालें]",
  "PGN 또는 FEN 붙여넣기": "PGN या FEN पेस्ट करें",
  "PGN에서 수를 읽을 수 없음": "PGN से कोई चाल नहीं पढ़ी जा सकी",
  "PGN이나 FEN으로 포지션을 정하면 엔진이 최선의 수와 오답 선택지를 골라 줌": "PGN या FEN से पोज़ीशन तय करें, इंजन सर्वश्रेष्ठ चाल और गलत विकल्प खुद चुन लेगा",
