  "도감의 이 길이 오프닝 {0}개 중에서 뽑음": "ओपनिंग डेक्स में इस लंबाई की {0} ओपनिंग में से चुना जाता है",
  "둘 수 없는 수가 포함됨": "इसमें अवैध चाल शामिल है",
  "둘 수 있는 수가 적어 퀴즈를 만들 수 없음": "क्विज़ बनाने के लिए वैध चालें बहुत कम हैं",
  "룰렛 보내기": "रूलेट भेजें",
