  "선택지 다시 고르기": "विकल्प दोबारा चुनें",
  "선택지(평가치는 백 기준)": "विकल्प (मूल्यांकन सफ़ेद के नज़रिये से)",
  "수는 1~19 사이로 입력.": "1 से 19 के बीच की संख्या दर्ज करें।",
  "아직 답하지 않음": "अभी तक जवाब नहीं दिया",
  "엔진이 분석하는 중…": "इंजन विश्लेषण कर रहा है…",
