  "연동된 서비스": "लिंक की गई सेवाएँ",
  "오답. 정답은 {0}": "गलत। सही उत्तर {0} है",
  "오프닝 룰렛": "ओपनिंग रूलेट",
  "이 길이의 오프닝이 도감에 없음": "ओपनिंग डेक्स में इस लंबाई की कोई ओपनिंग नहीं है",
  "이 포지션의 최선의 수는?": "इस पोज़ीशन में सर्वश्रेष्ठ चाल कौन-सी है?",
  "이미 끝난 포지션은 퀴즈로 낼 수 없음": "समाप्त हो चुकी पोज़ीशन से क्विज़ नहीं बन सकता",
  "읽을 수 없는 룰렛": "पढ़ी न जा सकने वाली रूलेट",
  "읽을 수 없는 퀴즈": "पढ़ा न जा सकने वाला क्विज़",
  "정답과 평가가 비슷한 수가 있어 정답이 모호할 수 있음": "कुछ चालों का मूल्यांकन सही उत्तर के करीब है, इसलिए उत्तर अस्पष्ट हो सकता है",
  "정한 수까지의 오프닝을 도감에서 무작위로 뽑음": "चुनी गई लंबाई की एक ओपनिंग ओपनिंग डेक्स से रैंडम रूप से चुनी जाती है",
  "정한 수까지의 오프닝을 도감에서 뽑는 룰렛 전송 (수를 비우면 고르는 창)": "चुनी गई लंबाई की ओपनिंग को ओपनिंग डेक्स से चुनने वाली रूलेट भेजें (संख्या खाली छोड़ें तो चयन विंडो खुलेगी)",
  "최선의 수 퀴즈": "सर्वश्रेष्ठ चाल क्विज़",
