  "퀴즈 만들기: 입력한 PGN·FEN 포지션에서 최선의 수를 오지선다로 맞히기": "क्विज़ बनाएँ: दिए गए PGN/FEN पोज़ीशन में सर्वश्रेष्ठ चाल बहुविकल्प से पहचानें",
  "퀴즈 보내기": "क्विज़ भेजें",
  "퀴즈": "क्विज़",
  "평가치는 백 기준": "मूल्यांकन सफ़ेद के नज़रिये से",
