  "Stockfish 18 Lite, depth 15로 고정. 연출 없이 분석이 끝나면 바로 리뷰 화면": "Stockfish 18 Lite और depth 15 तय। बिना एनिमेशन के, विश्लेषण पूरा होते ही रिव्यू स्क्रीन खुलती है",
  "빠른 리뷰 사용 중. 엔진과 리뷰 속도 고정": "क्विक रिव्यू चालू है। इंजन और रिव्यू की गति तय है",
  "평균": "सामान्य",
  "빠른 리뷰 분석 중": "क्विक रिव्यू के लिए विश्लेषण हो रहा है",
