  "최근 chess.com 대국 목록에서 바로 선택": "अपने हाल के chess.com खेलों में से सीधे चुनें",
  "설정에서 chess.com 계정 연동 시 이용 가능": "सेटिंग्स में chess.com खाता जोड़ने पर उपलब्ध",
  "대국 분석 중": "खेल का विश्लेषण हो रहा है",
  "찾은 후보 {0}개": "{0} उम्मीदवार मिले",
  "총 {0}수 재생": "कुल {0} {0|चाल|चालें} रीप्ले होंगी",
  "줄이기": "घटाएँ",
