  "상대 킹이 끝 랭크로 밀려나고 내 킹이 마주 서면, 룩 하나로 체크메이트할 수 있습니다.": "जब विरोधी राजा किनारे पर धकेल दिया जाए और आपका राजा उसके सामने खड़ा हो, तो एक ही रूक से शहमात हो सकता है।",
