  "소셜": "सोशल",
  "유산 {0}": "विरासत {0}",
  "좋아요 {0}개": "{0} पसंद",
  "표시할 게시물 없음": "दिखाने के लिए कोई पोस्ट नहीं",
  "공개 퍼즐은 소셜 탭 피드에서 누구나 풀 수 있고, 좋아요·리포스트·공유 가능": "सार्वजनिक पहेलियाँ सोशल टैब फ़ीड से कोई भी हल कर सकता है, और उन्हें पसंद, रीपोस्ट और साझा किया जा सकता है",
  "소셜 탭 맨 위 ‘일일 퍼즐’ 풀기": "सोशल टैब के सबसे ऊपर ‘दैनिक पहेली’ हल करें",
  "내 게시물은 리포스트할 수 없음": "अपनी पोस्ट को रीपोस्ट नहीं कर सकते",
  "아직 리포스트한 게시물 없음": "अभी कोई रीपोस्ट नहीं",
  "아직 올린 게시물 없음": "अभी कोई पोस्ट नहीं",
