  "스큐어에 가장 잘 쓰이는 기물은?": "स्क्यूअर के लिए सबसे अच्छे मोहरे कौन-से हैं?",
  "룩·비숍·퀸처럼 멀리 가는 기물": "हाथी, ऊँट और रानी जैसे दूर तक जाने वाले मोहरे",
