  "퀸으로 체크메이트할 때 내 킹이 하는 일은?": "रानी से शहमात देते समय आपका राजा क्या करता है?",
  "퀸을 지키며 상대 킹의 칸을 빼앗는다": "रानी को बचाता है और विरोधी राजा के खाने छीनता है",
