  "나이트와 룩의 가장자리 공격": "किनारे पर घोड़े और हाथी का हमला",
  "e7의 나이트가 g8과 g6을 막고, g7은 흑 자신의 폰이 막습니다. 이제 h파일만 막으면 됩니다.": "e7 का घोड़ा g8 और g6 को रोकता है, और g7 को काले का अपना प्यादा रोकता है। अब बस h फ़ाइल बंद करनी है।",
  "룩으로 h파일에서 체크메이트하세요.": "हाथी से h फ़ाइल पर शहमात दें।",
