  "아나스타샤 메이트에서 나이트가 하는 일은?": "अनास्तासिया मात में घोड़ा क्या करता है?",
  "킹이 피할 칸을 막는다": "राजा के भागने के खाने रोकता है",
  "룩을 지킨다": "हाथी को बचाता है",
  "h7 메이트": "h7 पर मात",
  "퀸과 비숍의 협력": "रानी और ऊँट का तालमेल",
  "d3 비숍이 대각선으로 h7을 지키고 있습니다. 흑의 h폰이 사라져 h7이 비어 있습니다.": "d3 का ऊँट विकर्ण से h7 को संभाल रहा है। काले का h प्यादा नहीं है, इसलिए h7 खाली है।",
  "퀸으로 h7에서 체크메이트하세요.": "रानी से h7 पर शहमात दें।",
  "퀸은 비숍이 지켜 잡을 수 없고, f8은 흑의 룩이, f7·g7은 흑의 폰이 막습니다.": "रानी को ऊँट बचा रहा है इसलिए उसे पकड़ा नहीं जा सकता; f8 को काला हाथी और f7·g7 को काले प्यादे रोकते हैं।",
  "이 패턴을 막으려면 흑은 무엇을 지켜야 할까요?": "इस पैटर्न को रोकने के लिए काले को क्या बचाना चाहिए?",
