  "a7의 룩이 7랭크를 막아 흑 킹은 8랭크 복도에 갇혔습니다.": "a7 का हाथी 7वीं रैंक रोकता है, इसलिए काला राजा 8वीं रैंक के गलियारे में फँस गया है।",
  "남은 룩으로 체크메이트하세요.": "दूसरे हाथी से शहमात दें।",
  "복도 메이트의 핵심은?": "गलियारा मात की कुंजी क्या है?",
  "한 기물이 킹이 피할 줄을 막고 다른 기물이 체크한다": "एक मोहरा राजा के भागने की पंक्ति रोकता है और दूसरा शह देता है",
  "킹을 중앙으로 부른다": "राजा को केंद्र में बुलाना",
  "폰을 프로모션한다": "प्यादे को प्रमोट करना",
  "백랭크 메이트도 복도 메이트의 한 종류입니다. 끝 랭크의 킹은 늘 이런 위험을 안고 있습니다.": "बैक रैंक मात भी गलियारा मात का ही एक प्रकार है। आख़िरी रैंक का राजा हमेशा इस ख़तरे में रहता है।",
  "가장자리의 나이트가 갈 수 있는 칸은 가운데에 있을 때보다?": "बीच की तुलना में किनारे का घोड़ा कितने खानों तक पहुँचता है?",
