  "고립 폰 바로 앞 칸이 내 기물에게 좋은 자리인 이유는?": "अकेले प्यादे के ठीक आगे वाला खाना आपके मोहरे के लिए अच्छा क्यों है?",
  "상대 폰이 그 칸을 공격할 수 없어서": "विरोधी प्यादे उस खाने पर हमला नहीं कर सकते",
  "내 킹과 가까워서": "वह मेरे राजा के पास है",
  "밝은 칸이라서": "वह हल्का खाना है",
  "상대에게 더블폰을 만드는 흔한 방법은?": "विरोधी को दोहरे प्यादे देने का आम तरीका क्या है?",
  "상대가 폰으로 되잡도록 기물을 교환한다": "मोहरे ऐसे बदलें कि विरोधी को प्यादे से वापस पकड़ना पड़े",
  "내 폰을 뒤로 물린다": "अपने प्यादे पीछे हटाएँ",
  "캐슬링한다": "कैसलिंग करें",
  "룩으로 상대 킹을 차단할 때 룩은 어디에 둘까요?": "हाथी से विरोधी राजा को काटते समय हाथी कहाँ रखें?",
  "상대 킹과 내 폰 사이의 줄": "विरोधी राजा और मेरे प्यादे के बीच की पंक्ति पर",
  "상대 킹 바로 옆": "विरोधी राजा के ठीक बगल में",
  "상대 폰이 한 수 먼저 프로모션한다면?": "अगर विरोधी का प्यादा एक चाल पहले प्रमोट हो जाए तो?",
  "경주 대신 그 폰을 막을 방법을 먼저 찾는다": "दौड़ने के बजाय पहले उस प्यादे को रोकने का तरीका ढूँढें",
  "그대로 경주한다": "फिर भी दौड़ते रहें",
