  "탁월한 수 판정을 4가지 상황별로 보완했습니다.": "शानदार चाल की पहचान चार अलग स्थितियों के लिए सुधारी।",
  "게임 리뷰에서 최선의 수를 두어도 평가치가 잠깐 바뀌었다가 돌아오던 문제를 고쳤습니다.": "गेम रिव्यू में सर्वश्रेष्ठ चाल चलने पर भी मूल्यांकन पल भर बदलकर लौटने की समस्या ठीक की।",
