  "일일 퍼즐 탭 첫 화면에 전날 퍼즐이 남아 있던 문제를 고쳤습니다.": "दैनिक पहेली टैब की पहली स्क्रीन पर पिछले दिन की पहेली बची रहने की समस्या ठीक की।",
  "긴 기보를 두거나 빠르게 넘기면 뒤로 갈수록 느려지던 문제를 고쳤습니다.": "लंबी चाल-सूची चलाने या तेज़ी से पलटने पर आगे जाते-जाते धीमा होने की समस्या ठीक की।",
  "스테일메이트와 3회 동형 반복 무승부를 알아봅니다.": "स्टेलमेट और तीन बार दोहराव वाला ड्रॉ अब पहचाना जाता है।",
