  "마스터 대국 목록에 없는 유명 대국을 개발자가 직접 등록할 수 있습니다.": "मास्टर बाज़ियों की सूची में न मौजूद मशहूर बाज़ियाँ अब डेवलपर खुद जोड़ सकता है।",
  "티어 여정 지도의 닫기 버튼을 오른쪽 위에 고정했습니다.": "टियर यात्रा मानचित्र का बंद करने का बटन ऊपर दाईं ओर तय किया।",
