  "나침반 모양의 오프닝 트리를 넣었습니다.": "कम्पास के आकार का ओपनिंग ट्री जोड़ा।",
  "도감 탭 오프닝 트리를 나침반 모양으로 새로 짰습니다. 1.e4·1.d4·1.c4·1.Nf3이 동서남북 네 방향으로 뻗어 나갑니다.": "संग्रह टैब का ओपनिंग ट्री कम्पास के रूप में बनाया, जिसमें 1.e4, 1.d4, 1.c4 और 1.Nf3 चार दिशाओं में फैलते हैं।",
